  const caption = [
    '📥 নতুন Task ' + id,
    'নাম: ' + u.name,
    'ফোন: ' + u.phone + ' (UID: ' + u.uid + ')',
    'Task: ' + task.title + ' (৳' + task.reward + ')',
    ...(note ? ['নোট: ' + note] : []),
    ...(buf ? [] : ['⚠ ফাইল আপলোড হয়নি – ইউজার proof WhatsApp-এ পাঠাবে']),
    '',
    '✅ Approve: এই মেসেজে reply করে  yes  লিখুন',
    '❌ Reject: এই মেসেজে reply করে  no  লিখুন',
    '(App task-এ ভিন্ন amount দিতে: yes 20)',
  ].join('\n').slice(0, 1000);
  if (buf) { await fs.promises.mkdir(UPLOADS, { recursive: true }); await fs.promises.writeFile(path.join(UPLOADS, fname), buf); }
