  addLog(`${id} submit – ${u.name} (${task.title})`);
  if (waOn()) {
    try {
      if (buf) {
        const mediaId = await waUpload(buf, mime, fname);
        const payload = mime === 'application/pdf'
          ? { type: 'document', document: { id: mediaId, filename: fname, caption } }
          : { type: 'image', image: { id: mediaId, caption } };
        sub.wamid = await waSend(payload);
      } else sub.wamid = await waText(caption);
      if (sub.wamid) db.wamap[sub.wamid] = { id };
    } catch (e) { sub.waError = true; console.error('[submit] WhatsApp পাঠানো যায়নি (Admin panel-এ দেখা যাবে):', e.message); }
  }
